// Recipes added by the user are kept in this browser and mixed into the list
export const loadCustom = (): Recipe[] => {
  try { return JSON.parse(localStorage.getItem('customRecipes') ?? '[]') as Recipe[] } catch { return [] }
}
export const saveCustom = (list: Recipe[]) => {
  try { localStorage.setItem('customRecipes', JSON.stringify(list)) } catch { /* ignore */ }
}
recipes.push(...loadCustom())

export const saveCustomIng = (list: Ing[]) => {
  try { localStorage.setItem('customIngredients', JSON.stringify(list)) } catch { /* ignore */ }
}
try { ingredients.push(...(JSON.parse(localStorage.getItem('customIngredients') ?? '[]') as Ing[])) } catch { /* ignore */ }
